import 'package:flutter/material.dart';

class LikeButton extends StatefulWidget {
  const LikeButton({super.key});

  @override
  State<LikeButton> createState() => _LikeButtonState();
}

class _LikeButtonState extends State<LikeButton> {
  // Состояние: лайкнуто или нет
  bool isLiked = false;

  // Метод переключения лайка
  void toggleLike() {
    setState(() {
      isLiked = !isLiked;  // true становится false, false становится true
    });
  }

  @override
  Widget build(BuildContext context) {
    return IconButton(
      // Размер иконки
      iconSize: 48,
      // Иконка зависит от состояния
      icon: Icon(
        isLiked 
            ? Icons.favorite          // Закрашенное сердце
            : Icons.favorite_border,  // Контур сердца
        // Цвет тоже зависит от состояния
        color: isLiked 
            ? Colors.red 
            : Colors.grey,
      ),
      // При нажатии вызываем метод
      onPressed: toggleLike,
    );
  }
}

