import 'package:flutter/material.dart';

// Пример с несколькими переменными состояния
class LoginForm extends StatefulWidget {
  const LoginForm({super.key});

  @override
  State<LoginForm> createState() => _LoginFormState();
}

class _LoginFormState extends State<LoginForm> {
  // === СОСТОЯНИЕ ===
  String email = '';
  String password = '';
  bool isPasswordVisible = false;
  bool isLoading = false;
  String? errorMessage;

  // === МЕТОДЫ ===

  void togglePasswordVisibility() {
    setState(() {
      isPasswordVisible = !isPasswordVisible;
    });
  }

  Future<void> login() async {
    // Начинаем загрузку
    setState(() {
      isLoading = true;
      errorMessage = null;
    });

    // Имитируем запрос к серверу
    await Future.delayed(const Duration(seconds: 2));

    // Проверяем данные (упрощённо)
    if (email.isEmpty || password.isEmpty) {
      setState(() {
        isLoading = false;
        errorMessage = 'Заполните все поля!';
      });
    } else {
      setState(() {
        isLoading = false;
      });
      // Успешный вход - переход на другой экран
    }
  }

  @override
  Widget build(BuildContext context) {
    return Padding(
      padding: const EdgeInsets.all(16),
      child: Column(
        children: [
          // Поле email
          TextField(
            decoration: const InputDecoration(labelText: 'Email'),
            onChanged: (value) {
              setState(() {
                email = value;
              });
            },
          ),
          const SizedBox(height: 16),

          // Поле пароля
          TextField(
            obscureText: !isPasswordVisible,
            decoration: InputDecoration(
              labelText: 'Пароль',
              suffixIcon: IconButton(
                icon: Icon(
                  isPasswordVisible 
                      ? Icons.visibility_off 
                      : Icons.visibility,
                ),
                onPressed: togglePasswordVisibility,
              ),
            ),
            onChanged: (value) {
              setState(() {
                password = value;
              });
            },
          ),
          const SizedBox(height: 24),

          // Сообщение об ошибке
          if (errorMessage != null)
            Text(
              errorMessage!,
              style: const TextStyle(color: Colors.red),
            ),

          const SizedBox(height: 16),

          // Кнопка входа
          SizedBox(
            width: double.infinity,
            child: ElevatedButton(
              onPressed: isLoading ? null : login,
              child: isLoading
                  ? const CircularProgressIndicator()
                  : const Text('Войти'),
            ),
          ),
        ],
      ),
    );
  }
}

import 'package:flutter/material.dart';

class TimerWidget extends StatefulWidget {
  const TimerWidget({super.key});

  @override
  State<TimerWidget> createState() => _TimerWidgetState();
}

class _TimerWidgetState extends State<TimerWidget> {
  int seconds = 0;
  late final Timer _timer;

  // === initState ===
  // Вызывается ОДИН РАЗ при создании
  @override
  void initState() {
    super.initState();  // ВАЖНО: вызвать первым!

    print('initState: Виджет создан!');

    // Запускаем таймер
    _timer = Timer.periodic(
      const Duration(seconds: 1),
      (timer) {
        setState(() {
          seconds++;
        });
      },
    );
  }

  // === build ===
  // Вызывается КАЖДЫЙ РАЗ при изменении состояния
  @override
  Widget build(BuildContext context) {
    print('build: Перерисовка UI (seconds = $seconds)');

    return Center(
      child: Column(
        mainAxisAlignment: MainAxisAlignment.center,
        children: [
          const Text(
            'Таймер',
            style: TextStyle(fontSize: 24),
          ),
          const SizedBox(height: 16),
          Text(
            '$seconds сек',
            style: const TextStyle(
              fontSize: 48,
              fontWeight: FontWeight.bold,
            ),
          ),
        ],
      ),
    );
  }

  // === dispose ===
  // Вызывается ОДИН РАЗ при удалении виджета
  @override
  void dispose() {
    print('dispose: Виджет удаляется!');

    // ВАЖНО: останавливаем таймер!
    // Иначе будет утечка памяти
    _timer.cancel();

    super.dispose();  // ВАЖНО: вызвать последним!
  }
}

// Не забудьте импортировать:
// import 'dart:async';

