import 'package:flutter/material.dart';

// StatefulWidget с параметрами
class Counter extends StatefulWidget {
  // === ПАРАМЕТРЫ (неизменяемые) ===
  final int initialValue;           // Начальное значение
  final int step;                    // Шаг изменения
  final void Function(int)? onChanged;  // Callback при изменении

  const Counter({
    super.key,
    this.initialValue = 0,
    this.step = 1,
    this.onChanged,
  });

  @override
  State<Counter> createState() => _CounterState();
}

class _CounterState extends State<Counter> {
  // === СОСТОЯНИЕ (изменяемое) ===
  late int count;

  @override
  void initState() {
    super.initState();
    // Инициализируем из параметра widget
    count = widget.initialValue;
  }

  void increment() {
    setState(() {
      count += widget.step;  // Используем параметр step
    });
    // Вызываем callback, если он есть
    widget.onChanged?.call(count);
  }

  void decrement() {
    setState(() {
      count -= widget.step;
    });
    widget.onChanged?.call(count);
  }

  @override
  Widget build(BuildContext context) {
    return Row(
      mainAxisSize: MainAxisSize.min,
      children: [
        IconButton(
          onPressed: decrement,
          icon: const Icon(Icons.remove),
        ),
        Text(
          '$count',
          style: const TextStyle(fontSize: 24),
        ),
        IconButton(
          onPressed: increment,
          icon: const Icon(Icons.add),
        ),
      ],
    );
  }
}

// === ИСПОЛЬЗОВАНИЕ ===

class ShoppingCart extends StatelessWidget {
  const ShoppingCart({super.key});

  @override
  Widget build(BuildContext context) {
    return Column(
      children: [
        const Text('Количество товара:'),
        Counter(
          initialValue: 1,    // Начинаем с 1
          step: 1,            // Шаг = 1
          onChanged: (value) {
            // Получаем новое значение!
            print('Новое количество: $value');
          },
        ),
      ],
    );
  }
}

